using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    [ColumnName("ChurnedText")]
    public string ChurnedText { get; set; } = string.Empty;
}

using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<CustomerData, ChurnPrediction> _predictionEngine;
    private readonly double _accuracy;
    private readonly double _auc;

    public ChurnModelService(IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);

        var csvPath = Path.Combine(env.ContentRootPath, "Data", "customers.csv");
        var dataView = _mlContext.Data.LoadFromTextFile<CustomerData>(
            csvPath, hasHeader: true, separatorChar: ',');

        // Map "Yes"/"No" text to boolean Label column
        var labelLookup = new[]
        {
            new LabelMapping { ChurnedText = "Yes", Label = true },
            new LabelMapping { ChurnedText = "No", Label = false }
        };
        var labelLookupData = _mlContext.Data.LoadFromEnumerable(labelLookup);

        var pipeline = _mlContext.Transforms.Conversion.MapValue(
                "Label", labelLookupData,
                labelLookupData.Schema["ChurnedText"],
                labelLookupData.Schema["Label"],
                "ChurnedText")
            .Append(_mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
            .Append(_mlContext.Transforms.Concatenate("Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                labelColumnName: "Label", featureColumnName: "Features"));

        // Cross-validate for metrics
        var cvResults = _mlContext.BinaryClassification.CrossValidate(
            dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");

        _accuracy = cvResults.Average(r => r.Metrics.Accuracy);
        _auc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);

        // Train final model on all data
        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(_model);
    }

    public ChurnPrediction Predict(CustomerData input) => _predictionEngine.Predict(input);

    public object GetMetrics() => new { Accuracy = _accuracy, AUC = _auc };

    private class LabelMapping
    {
        public string ChurnedText { get; set; } = string.Empty;
        public bool Label { get; set; }
    }
}

